def extract_xml(res):
    match = re.search(r'<description>(.*?)</description>', res, re.DOTALL)
    if match:
        description_content = match.group(0)  # 使用group(0)获取整个匹配的字符串
        return description_content
    match = re.search(r'<description>(.*?)</description>', res, re.DOTALL)
    if match:
        description_content = match.group(0)  # 使用group(0)获取整个匹配的字符串
        return description_content
    else:
        return "nan"


