def get_result(model, prompt):
    API_VERSION = "v2.03"
    def get_simple_auth(source, SecretId, SecretKey):
        dateTime = datetime.utcnow().strftime('%a, %d %b %Y %H:%M:%S GMT')
        auth = "hmac id=\"" + SecretId + "\", algorithm=\"hmac-sha1\", headers=\"date source\", signature=\""
        signStr = "date: " + dateTime + "\n" + "source: " + source
        sign = hmac.new(SecretKey.encode(), signStr.encode(), hashlib.sha1).digest()
        sign = base64.b64encode(sign).decode()
        sign = auth + sign + "\""
        return sign, dateTime
    
    
    class Api:
        def __init__(self, host, user, apikey, model):
            if model == "gemini":
                # self.model_marker = "api_google_gemini-1.5-pro-002"
                # self.model = "gemini-1.5-pro-002"
                self.model_marker = "api_google_gemini-2.5-pro"
                self.model = "gemini-2.5-pro"
            elif model == "claude":
                self.model_marker = "api_anthropic_claude-3-5-sonnet-20241022"
                self.model = "claude-3-5-sonnet-20241022" 
            elif model == "gpt":
                self.model_marker = "api_azure_openai_gpt-4o"
                self.model = "api_azure_openai_gpt-4o" 
            self.host = host
            self.user = user
            self.apikey = apikey
            self.timeout = 600  # 超时时间
    
        def get_header(self):
            source = 'xxxxxx'  # 签名水印值，可填写任意值
            sign, dateTime = get_simple_auth(source, self.user, self.apikey)
            headers = {'Apiversion': API_VERSION, 'Authorization': sign, 'Date': dateTime, 'Source': source}
            return headers

        def infer(self, request_id, prompt):
            base_url = self.host + '/api/v1/data_eval'
            if self.model_marker == "api_anthropic_claude-3-5-sonnet-20241022":
                data = {
                "request_id": request_id,
                "model_marker": self.model_marker ,
                "messages": [
                    {
                        "role": "user",
                        "content": [
                            {
                                "type": "text",
                                "value": prompt
                            }

                        ]
                    }
                ],
                "params": {
                    "model": self.model,
                    "max_tokens": 1024
                },
                "timeout": 600
            }
            else:
                data = {
                    "request_id": request_id,
                    "model_marker": self.model_marker ,
                    "messages": [
                        {
                            "role": "user",
                            "content": [
                                {
                                    "type": "text",
                                    "value": prompt
                                }
    
                            ]
                        }
                    ],
                    "params": {
                        "model": self.model,
                    },
                    "timeout": 600
                }
    
            headers = dict(self.get_header())
            # print(f"data:\n {data}")
            rsp = requests.post(url=base_url, headers=headers, json=data, timeout=self.timeout)
            # print(rsp.text)
            return rsp
    
    for i in range(60):
        request_id = str(uuid.uuid4())
        try:
            HOST = "trpc-gpt-eval.production.polaris"  # 生产
            api = Api("http://{}:8080".format(HOST), APP_ID, APP_TOKEN, model) # 生产
            ret = api.infer(request_id, prompt)
            print(ret.json()["answer"][0]["value"])
            return ret.json()["answer"][0]["value"]
        except Exception as e:
            print(request_id, str(e))
            # print(ret.text)
            time.sleep(1)
    print('####超过请求次数没有结果###')
    return None


def count_result(model_tag, file_name, eval_QAs_col):
    df = pd.read_csv(file_name)
    ans_stat = []
    for i in tqdm.tqdm(range(len(df))):
        gt_QAs = df.loc[i]["questions"]
        eval_QAs = df.loc[i][eval_QAs_col]
        try:
            gt_QAs = eval(gt_QAs.replace("\n",","))
            eval_QAs = eval(eval_QAs.replace("\n",","))
            if len(gt_QAs) != len(eval_QAs):
                print("测试结果和标注结果长度不一致，跳过！")
                continue
        except:
            print("测试结果和标注结果长度不一致，跳过！")
            continue
            
        for j in range(len(gt_QAs)):
            gt_ans = gt_QAs[j]["answer"].lower()
            if eval_QAs[j]["answer"] == None:
                continue
            eval_ans = eval_QAs[j]["answer"].split("@")[0].lower()
            if eval_ans in ["yes", "no"] or gt_ans == eval_ans:
                ans_stat.append(int(gt_ans == eval_ans))
            elif eval_ans == "unanswerable":
                ans_stat.append(2)
            else:
                print(eval_ans)
                continue
    
    # 计算总数
    total = len(ans_stat)

    # 计算每种结果的数量
    correct_count = ans_stat.count(1)
    incorrect_count = ans_stat.count(0)
    uncertain_count = ans_stat.count(2)  

    # 计算比例
    accuracy = correct_count / total
    error_rate = incorrect_count / total
    uncertainty_rate = uncertain_count / total

    # 输出结果
    print(f"测试条数: {total}")
    print(f"准确率: {accuracy:.2%}")
    print(f"错误率: {error_rate:.2%}")
    print(f"不确定率: {uncertainty_rate:.2%}")

    # 保存到文件
    save_file = Path(file_name).parent / f"{Path(file_name).stem}_score.csv"
    score = [dict(
        model_tag=model_tag,
        count=total,
        accuracy=accuracy,
        error_rate=error_rate,
        uncertainty_rate=uncertainty_rate,
    )]
    score = pd.DataFrame(score)
    score.to_csv(save_file, index=False)
    print(f"Final score saved to {save_file}")


def fetch_results(model, prompts):
    results = [None] * len(prompts)  # 初始化结果列表
    with concurrent.futures.ThreadPoolExecutor() as executor:
        future_to_index = {executor.submit(get_result, model, prompt): index for index, prompt in enumerate(prompts)}
        for future in tqdm.tqdm(concurrent.futures.as_completed(future_to_index)):
            index = future_to_index[future]
            try:
                result = future.result()
                results[index] = result  # 将结果放入正确的位置
            except Exception as e:
                print(f"请求失败: {prompts[index]} - 错误: {e}")
                results[index] = None  # 或者您可以选择其他的错误处理方式
    return results


def parse_arguments():
    parser = argparse.ArgumentParser()
    parser.add_argument('--csv', type=str, required=True, help='Path to the input CSV file')
    parser.add_argument('--result-dir', type=str, required=True, help='Path to the result directory')
    parser.add_argument('--model-tag', type=str, required=True, help='A model name to identify the results')
    parser.add_argument('--caption-col', type=str, default="answer")
    parser.add_argument("--start-index", type=int, default=None)
    parser.add_argument("--end-index", type=int, default=None)
    parser.add_argument("--only-calc-score", action="store_true", help='Skip calling gemini. Only calculate final score.')
    parser.add_argument("--enable-pool", action="store_true", help="Whether to use multiple threads to request.")
    return parser.parse_args()


def safe_save_file(df, save_path):
    save_path = Path(save_path)
    tmp_save_path = save_path.parent / f"{save_path.name}.tmp"
    df.to_csv(tmp_save_path, index=False)
    if save_path.exists():
        save_path.unlink()
    tmp_save_path.rename(save_path)


if __name__ == "__main__":
    args = parse_arguments()
    result_dir = Path(args.result_dir)
    assert result_dir.exists(), f"Result directory {result_dir} does not exist."
    print("===============================================================================================")
    print(f"Processing results from {result_dir}")
    print("===============================================================================================")
    results_df = pd.concat([pd.read_csv(f, header=0) for f in result_dir.glob("*.csv")])
    results_df.drop_duplicates(subset=["index"], inplace=True)
    results_df.sort_values(by="index", ascending=True, inplace=True)
    results_df.set_index("index", inplace=True)

    df = pd.read_csv(args.csv)
    df.set_index("index", inplace=True)
    assert len(df) == len(results_df), f"Length mismatch: {len(df)} != {len(results_df)}"

    res_col = f"{args.caption_col}_QAs"

    output_file = Path(args.result_dir).parent / f"{Path(args.result_dir).stem}_capsbench.csv"
    if output_file.exists():
        output_df = pd.read_csv(output_file, header=0)
        df[res_col] = output_df[res_col]

    if not args.only_calc_score:
        for i, item in tqdm.tqdm(df.iterrows(), total=len(df)):
            QAs_cap = []
            eval_caption = results_df.loc[i, args.caption_col]
            if str(eval_caption) == "nan":
                df.loc[i, res_col] = None
                continue
            # 如果结果已经存在, 则跳过

            QAs = item["questions"]
            QAs = QAs.replace("\n", ",")
            # TODO: remove eval operation
            QAs = eval(QAs)
            if args.enable_pool:
                prompts = [prompt_template.format(eval_caption, QA['question']) for QA in QAs]
                results = fetch_results(model="gemini", prompts=prompts)
                for j, QA in enumerate(QAs):
                    QA["answer"] = results[j]
                    QAs_cap.append(QA)
            else:
                for QA in QAs:
                    Q = QA['question']
                    prompt = prompt_template.format(eval_caption, Q)
                    QA["answer"] = get_result(model="gemini", prompt=prompt)
                    QAs_cap.append(QA)
            df.loc[i, res_col] = json.dumps(QAs_cap)
            # 提前保存
            if i % 5 == 0:
                safe_save_file(df, output_file)
        safe_save_file(df, output_file)
    print(f"Results save to {output_file}")

    count_result(model_tag=args.model_tag, file_name=output_file, eval_QAs_col=res_col)

